html,body { margin:0; padding:0; font:16px/1.4 -apple-system, Helvetica, Arial, sans-serif; }
/* The same three containers `t17b-page.html` carries, each now holding an
   `<iframe>` instead of an element. The question T17b answered INSIDE one
   document is open again at the frame boundary, because the child document's
   root inherits nothing from the `<iframe>` element. */
#op-box   { opacity:0; }
#vis-box  { visibility:hidden; }
#none-box { display:none; }
/* The NEGATIVE control, and it carries the nested frame too: a cross-frame
   cascade that marks every child document instead of the ones under a
   transparent owner passes every positive assertion and fails here. */
#plain-box { }
iframe { display:block; width:260px; height:120px; border:0; }
/* The OWNER WITH NO READING. `display: contents` is what T17b's census found generates no
   layout entry at all, so the `<iframe>` itself would arrive with `computed: None` while
   sitting inside the transparent container — the one shape where "read the owner's cascaded
   flag" has nothing to read. Whether Chrome then lays the child document out at all is the
   measurement; the spec says `display: contents` computes to `none` on a replaced element,
   and a spec sentence is not a reading. */
/* The `<iframe>` DECLARES the transparency itself, with nothing hiding above it. It separates
   "the boundary reads the owner's CASCADED flag" from "the boundary reads any flag at all":
   read the owner's own styles row instead of the cascade's output and this one still works
   while `#op-frame`'s child goes visible. */
#self-frame     { opacity:0; }
#contents-box   { opacity:0; }
#contents-frame { display:contents; }

// `?child=<url>&inner=<url>`. The `op` and `plain` frames get the INNER frame as well, so
// the capture carries a frame nested inside a frame on both the positive and the negative
// side — a one-hop cross-frame cascade passes a single-frame fixture, which is the trap this
// task line has fallen into three times.
var p = new URL(location.href).searchParams;
var child = p.get('child');
var inner = p.get('inner');
function wire(id, tag, withInner) {
  var f = document.getElementById(id);
  if (!child) { f.remove(); return; }
  var u = child + '?tag=' + encodeURIComponent(tag);
  if (withInner && inner) { u += '&inner=' + encodeURIComponent(inner); }
  if (p.get('modal')) { u += '&modal=1'; }
  f.src = u;
}
wire('op-frame', 'op', true);
wire('vis-frame', 'vis', false);
wire('none-frame', 'none', false);
wire('plain-frame', 'plain', true);
wire('self-frame', 'self', false);
wire('contents-frame', 'contents', false);

html,body { margin:0; padding:0; font:14px/1.2 monospace; background:#fff; }
#c-probe { position:absolute; left:10px; top:10px; width:120px; height:18px; background:#cfc; }
#c-btn   { position:absolute; left:10px; top:34px; }
#c-inner { position:absolute; left:10px; top:62px; width:200px; height:50px; border:0; }

// Every id gets the `?tag=` suffix, because all four frames load THIS file: without it the
// capture carries four `#c-probe`s and an assertion naming one of them would be about
// whichever document the lookup happened to reach first.
var p = new URL(location.href).searchParams;
var tag = p.get('tag') || 'x';
var ids = Array.prototype.slice.call(document.querySelectorAll('[id]'));
ids.forEach(function (el) { el.id = el.id + '-' + tag; });
var inner = p.get('inner');
var f = document.getElementById('c-inner-' + tag);
if (inner) { f.src = inner + '?tag=' + encodeURIComponent(tag); } else { f.remove(); }
var dlg = document.getElementById('c-dlg-' + tag);
if (p.get('modal')) { dlg.showModal(); } else { dlg.remove(); }

